"""recompute_dmi_strata.py -- RECORD AUDIT of NEXT_EXPERIMENTS_ROOM16e4.md §7.2 (prior DMI): the two report-only strata tables.
Unlike recompute_room_strata.py (transcription only) this one ALSO recomputes the strata independently:
  * the test channels of trials 0..2559 at -3 / 0 / +3 dB are regenerated by replaying the trial stream (common.trial_rng; the
    generator, code and transmit objects come from runner.build_point -- the registered tools dmc_leak_strata.py / rank_strata.py are
    NOT imported and NOT run: they would overwrite the tracked result files);
  * alignment: R5-genie is re-run on the FIRST 40 and on the LAST 40 replayed trials and its blk_err AND ber trajectories must equal
    the raw chunk arrays bit for bit (the tools check the first 40 blk_err only);
  * failures come from this script's own chunk reader (no analysis.load_raw);
  * leak distance d = min_train ||h - x||^2 / ||h||^2 with an own chunked implementation (float64, explicit differences on the
    100 nearest candidates per test channel to avoid the cancellation of the expanded form);
  * rank strata by s1^2 / sum s^2 with numpy.linalg.svd.
Every expected value is retyped from the record (§7.1 appendix, §7.2 bullets and table).

usage (cwd = ~/t2/conf):  CUDA_VISIBLE_DEVICES= OMP_NUM_THREADS=8 taskset -c 0-15 ~/miniforge3/envs/torch/bin/python -B \
    results/review_next/prereg_audit_2026-10-11/recompute_dmi_strata.py > .../recompute_dmi_strata.out
"""
import glob
import os
import re
import sys

import numpy as np

CONF = "/home/HTJ/t2/conf"
sys.path.insert(0, os.path.join(CONF, "code"))
N, CHUNK = 2560, 40
BS, V1, GEN = "M-ours-bstar", "M-ours-dscore-C-V1", "R5-genie"
NC = [0, 0]

# ---- retyped from the record
REC_LEAK = {-3: (0.1803, 0.074, (189, 74, 60, 29, 0.311), (2371, 811, 769, 292, 0.081)),
            0: (0.1813, 0.066, (169, 12, 19, 4, -0.875), (2391, 161, 130, 36, 0.248)),
            3: (0.1810, 0.064, (165, 2, 2, 0, 0.000), (2395, 21, 17, 4, 0.235))}
REC_LEAK_POOL = ((523, 88, 81, 33, 0.127), (7157, 993, 916, 332, 0.116))
REC_RANK = {-3: (0.872, [(59, 0.023, 0.339, 0.661, 0.678, 20, 39, 40), (2040, 0.797, 0.136, 0.336, 0.360, 278, 686, 735),
                         (457, 0.179, 0.050, 0.225, 0.241, 23, 103, 110), (4, 0.002, 0.000, 0.250, 0.000, 0, 1, 0)]),
            0: (0.874, [(52, 0.020, 0.115, 0.327, 0.308, 6, 17, 16), (2110, 0.824, 0.016, 0.060, 0.071, 34, 127, 149),
                        (391, 0.153, 0.000, 0.013, 0.020, 0, 5, 8), (7, 0.003, 0.000, 0.000, 0.000, 0, 0, 0)]),
            3: (0.873, [(53, 0.021, 0.019, 0.075, 0.094, 1, 4, 5), (2096, 0.819, 0.001, 0.006, 0.009, 3, 13, 18),
                        (408, 0.159, 0.000, 0.005, 0.000, 0, 2, 0), (3, 0.001, 0.000, 0.000, 0.000, 0, 0, 0)])}
TOT = {-3: (885, 829, 321), 0: (173, 149, 40), 3: (23, 19, 4)}
EDGES = ((0.95, 1.01), (0.80, 0.95), (0.60, 0.80), (0.0, 0.60))


def chk(label, got, exp):
    NC[0] += 1
    if got != exp:
        NC[1] += 1
        print(f"    DIFF  {label}: recomputed {got!r}  record {exp!r}")


def read(tag, snr):
    out = {}
    fs = sorted(glob.glob(os.path.join(CONF, f"raw_{tag}", f"D2_C2_DMI_Nr8_T16_Tp4_dft_snr{snr}_skip*_n40.npz")),
                key=lambda f: int(re.search(r"_skip(\d+)_", f)[1]))
    assert len(fs) == 64
    zs = [np.load(f) for f in fs]
    for arm in (BS, V1, GEN):
        be = np.concatenate([z[arm + "|blk_err"] for z in zs]).astype(float)
        out[arm] = np.where(np.isfinite(be), be, 1.0)[:, -1]
    out["g_blk"] = np.concatenate([z[GEN + "|blk_err"] for z in zs])
    out["g_ber"] = np.concatenate([z[GEN + "|ber"] for z in zs])
    return out


def nn_dist(h, X):
    """min_j ||h_i - X_j||^2 / ||h_i||^2: candidates by the expanded form, then exact differences on the 100 nearest."""
    a2 = (np.abs(h) ** 2).sum(1)
    x2 = (np.abs(X) ** 2).sum(1)
    best = np.full(len(h), np.inf)
    for i0 in range(0, len(h), 256):
        hb = h[i0:i0 + 256]
        D = a2[i0:i0 + 256, None] + x2[None] - 2 * (hb @ X.conj().T).real
        idx = np.argpartition(D, 100, axis=1)[:, :100]
        for r in range(len(hb)):
            best[i0 + r] = (np.abs(X[idx[r]] - hb[r][None]) ** 2).sum(1).min()
    return best / a2


def R(b, v, g):
    return round((b - v) / (b - g), 3) if b - g > 0 else float("nan")


def main():
    import arms as A
    import common as C
    import runner
    runner._init("DMIB16e4")
    c = C.CELLS["C2"]
    X = A.training_set("D2", "DMI", c["Nr"], c["Nt"], 160000)
    print(f"# recompute_dmi_strata.py -- training set {X.shape} {X.dtype}; replay of the DMI trial stream at -3 / 0 / +3 dB")
    pool = {"lt": np.zeros(4, int), "ge": np.zeros(4, int)}
    for snr in (-3, 0, 3):
        raw = read("DMIB16e4", snr)
        chk(f"{snr:+d} raw totals (b*, V1, genie)", tuple(int(raw[a].sum()) for a in (BS, V1, GEN)), TOT[snr])
        P = runner.build_point("D2", "C2", "DMI", float(snr), 160000)
        code, gen, first = P["code"], P["gen"], P["arms"][GEN]
        rng = C.trial_rng("D2", "DMI", c["Nr"], c["T"], c["Tp"], float(snr))
        hF = np.empty((N, c["Nr"] * c["Nt"]), complex)
        share = np.empty(N)
        same_blk = same_ber = True
        for tr in range(N):
            H = gen.sample(rng)
            u = rng.integers(0, 2, code.K)
            perm = rng.permutation(code.Ns)
            _, Y = first.transmit(u, perm, H, rng)
            hF[tr] = H.reshape(-1, order="F")
            s = np.linalg.svd(H, compute_uv=False) ** 2
            share[tr] = s[0] / s.sum()
            if tr < 40 or tr >= N - 40:
                r = first.run(Y, H, u, perm, C.N_ITER)
                same_blk &= bool(np.array_equal(np.asarray(r["blk_err"]), raw["g_blk"][tr], equal_nan=True))
                same_ber &= bool(np.array_equal(np.asarray(r["ber"]), raw["g_ber"][tr], equal_nan=True))
        print(f"\n{snr:+d} dB: alignment (R5-genie on replayed trials 0..39 and 2520..2559; blk_err {same_blk}, ber trajectories {same_ber})")
        chk(f"{snr:+d} alignment first 40 + last 40 (blk_err, ber) bit-identical", (same_blk, same_ber), (True, True))
        d = nn_dist(hF, X)
        dC = nn_dist(hF.reshape(N, c["Nt"], c["Nr"]).transpose(0, 2, 1).reshape(N, -1), X) if snr == -3 else None   # the other vec order, as a sanity check
        med, sh = float(np.median(d)), float(np.mean(d < 0.1))
        print(f"  leak: d median {med:.4f}, share d < 0.1 = {sh:.3f}" + (f"   [row-major vec instead: median {np.median(dC):.4f} -> column-major is the training set's order]" if dC is not None else ""))
        e = REC_LEAK[snr]
        chk(f"{snr:+d} leak d median (4 dp)", round(med, 4), e[0]); chk(f"{snr:+d} leak share (3 dp)", round(sh, 3), e[1])
        for lab, m, er in (("lt", d < 0.1, e[2]), ("ge", d >= 0.1, e[3])):
            row = (int(m.sum()), int(raw[BS][m].sum()), int(raw[V1][m].sum()), int(raw[GEN][m].sum()))
            pool[lab] += np.array(row)
            print(f"    d {'<' if lab == 'lt' else '>='} 0.1  n={row[0]:5d}  b* {row[1]}  V1 {row[2]}  genie {row[3]}  R = {R(*row[1:])}")
            chk(f"{snr:+d} leak {lab} row (n, b*, V1, genie)", row, er[:4]); chk(f"{snr:+d} leak {lab} R", R(*row[1:]), er[4])
        med_s = float(np.median(share))
        print(f"  rank: share median {med_s:.3f}")
        chk(f"{snr:+d} rank share median (3 dp)", round(med_s, 3), REC_RANK[snr][0])
        rows = []
        for lo, hi in EDGES:
            m = (share >= lo) & (share < hi)
            n_ = int(m.sum())
            g, v, b = (int(raw[a][m].sum()) for a in (GEN, V1, BS))
            rows.append((n_, round(n_ / N, 3), round(g / n_, 3), round(v / n_, 3), round(b / n_, 3), g, v, b))
            print(f"    share [{lo:.2f}, {min(hi, 1):.2f})  n={n_:5d} ({n_ / N:.3f})  BLER genie {g / n_:.3f} V1 {v / n_:.3f} b* {b / n_:.3f}  failures {g} / {v} / {b}")
        chk(f"{snr:+d} rank rows (n, share, BLER genie/V1/b*, failures genie/V1/b*)", rows, REC_RANK[snr][1])
        chk(f"{snr:+d} rank n sum / failure sums", (sum(r[0] for r in rows), sum(r[5] for r in rows), sum(r[6] for r in rows), sum(r[7] for r in rows)),
            (N, TOT[snr][2], TOT[snr][1], TOT[snr][0]))
    for lab, er in (("lt", REC_LEAK_POOL[0]), ("ge", REC_LEAK_POOL[1])):
        row = tuple(int(x) for x in pool[lab])
        print(f"pooled d {'<' if lab == 'lt' else '>='} 0.1: n={row[0]} b* {row[1]} V1 {row[2]} genie {row[3]} R = {R(*row[1:])}")
        chk(f"leak pooled {lab} row", row, er[:4]); chk(f"leak pooled {lab} R", R(*row[1:]), er[4])
    chk("§7.1 label appendix '판정점 시행에서는 0.074 / 0.066 / 0.064'", tuple(REC_LEAK[s][1] for s in (-3, 0, 3)), (0.074, 0.066, 0.064))
    chk("rank-1 layer (share >= 0.95) 0.020-0.023 of the trials (§0 test-pool rank-1 0.021)", [REC_RANK[s][1][0][1] for s in (-3, 0, 3)], [0.023, 0.020, 0.021])
    # transcription of the two recorded files (text)
    for name in ("DMIB16e4_leak_strata.txt", "DMIB16e4_rank_strata.txt"):
        t = open(os.path.join(CONF, "results/review_next", name)).read()
        chk(f"{name}: alignment OK lines (3) + 'alignment OK at every SNR' + header git 29cf411d", (t.count("bit-identical): OK"), "alignment OK at every SNR" in t, "# git commit  : 29cf411d" in t), (3, True, True))
    t = open(os.path.join(CONF, "results/review_next", "DMIB16e4_leak_strata.txt")).read()
    for snr in (-3, 0, 3):
        e = REC_LEAK[snr]
        chk(f"leak file {snr:+d} lines == record", all(s in t for s in (
            f"d median {e[0]:.4f}, share d < 0.1 = {e[1]:.3f}",
            f"n={e[2][0]:5d}  failures b* {e[2][1]:4d}  V1 {e[2][2]:4d}  genie {e[2][3]:4d}  R = {e[2][4]:.3f}",
            f"n={e[3][0]:5d}  failures b* {e[3][1]:4d}  V1 {e[3][2]:4d}  genie {e[3][3]:4d}  R = {e[3][4]:.3f}")), True)
    print(f"\n## SUMMARY: {NC[0]} values checked, {NC[1]} differ from the record")


if __name__ == "__main__":
    main()
